// ***************
// Filename: watchdog_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of watchdog: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to watchdog's logic on named ports, its
//   status comes back on input ports. Watchdog timer: prescaler, timeout,
//   pre-timeout interrupt, window, keyed kick, lock. Generated by
//   ip/scripts/regmap_gen.py from watchdog_regs.json: edit the JSON and
//   regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "WDOG" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        CMD  control (EN and LOCK are ignored once LOCK is
//                       set)
//                       [0] EN: 1: watchdog running
//                       [1] WINDOW_EN: 1: a kick before WINDOW_OPEN is early
//                         (reset)
//                       [2] LOCK: 1: EN can no longer be changed (until
//                         reset)
//     0x14 TIMEOUT     RW   reset after this many ticks without a kick, reset
//                       0x3E8
//     0x18 PRESCALE    RW   clock cycles per tick - 1, reset 0x0
//     0x1C PRETIMEOUT  RW   pre-timeout interrupt after this many ticks (0:
//                       off), reset 0x0
//     0x20 WINDOW_OPEN RW   earliest legal kick, ticks (window mode), reset
//                       0x0
//     0x24 KICK        WO   write 0x5AFEC0DE to restart the count (other
//                       values: bad key)
//     0x28 STATUS      CMD  flags, write 1 to clear
//                       [0] PRETIMEOUT: pre-timeout reached (interrupt)
//                       [1] EXPIRED: timeout reached (reset)
//                       [2] EARLY: kick before WINDOW_OPEN
//                       [3] BAD_KEY: kick with a wrong key
//     0x2C COUNT       RO   current tick count
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-16
module watchdog_regs (
  input  logic          aclk,             // clock
  input  logic          aresetn,          // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: watchdog_regs_if.regs (src/include/watchdog_regs_if.sv) {ctrl_i=sts_ctrl ctrl_o=cfg_ctrl ctrl_wr_o=cfg_ctrl_wr timeout_o=cfg_timeout timeout_wr_o=cfg_timeout_wr prescale_o=cfg_prescale prescale_wr_o=cfg_prescale_wr pretimeout_o=cfg_pretimeout pretimeout_wr_o=cfg_pretimeout_wr window_open_o=cfg_window_open window_open_wr_o=cfg_window_open_wr kick_o=cfg_kick kick_wr_o=cfg_kick_wr status_i=sts_status status_o=cfg_status status_wr_o=cfg_status_wr count_i=sts_count}
  watchdog_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [3-1:0] ctrl_i;
  logic [3-1:0] ctrl_o;
  logic ctrl_wr_o;
  logic [32-1:0] timeout_o;
  logic timeout_wr_o;
  logic [32-1:0] prescale_o;
  logic prescale_wr_o;
  logic [32-1:0] pretimeout_o;
  logic pretimeout_wr_o;
  logic [32-1:0] window_open_o;
  logic window_open_wr_o;
  logic [32-1:0] kick_o;
  logic kick_wr_o;
  logic [4-1:0] status_i;
  logic [4-1:0] status_o;
  logic status_wr_o;
  logic [32-1:0] count_i;
  assign ctrl_i = r.sts_ctrl;
  assign r.cfg_ctrl = ctrl_o;
  assign r.cfg_ctrl_wr = ctrl_wr_o;
  assign r.cfg_timeout = timeout_o;
  assign r.cfg_timeout_wr = timeout_wr_o;
  assign r.cfg_prescale = prescale_o;
  assign r.cfg_prescale_wr = prescale_wr_o;
  assign r.cfg_pretimeout = pretimeout_o;
  assign r.cfg_pretimeout_wr = pretimeout_wr_o;
  assign r.cfg_window_open = window_open_o;
  assign r.cfg_window_open_wr = window_open_wr_o;
  assign r.cfg_kick = kick_o;
  assign r.cfg_kick_wr = kick_wr_o;
  assign status_i = r.sts_status;
  assign r.cfg_status = status_o;
  assign r.cfg_status_wr = status_wr_o;
  assign count_i = r.sts_count;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "WDOG";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_TIMEOUT = 8'h14;
  localparam logic [7:0] A_PRESCALE = 8'h18;
  localparam logic [7:0] A_PRETIMEOUT = 8'h1C;
  localparam logic [7:0] A_WINDOW_OPEN = 8'h20;
  localparam logic [7:0] A_KICK = 8'h24;
  localparam logic [7:0] A_STATUS = 8'h28;
  localparam logic [7:0] A_COUNT = 8'h2C;
  localparam int MAP_WORDS = 12;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] timeout_q;
  logic [31:0] prescale_q;
  logic [31:0] pretimeout_q;
  logic [31:0] window_open_q;
  logic [31:0] kick_q;
  logic [31:0] status_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      ctrl_q <= '0;
      ctrl_wr_o <= 1'b0;
      timeout_q <= 32'h3E8;
      timeout_wr_o <= 1'b0;
      prescale_q <= 32'h0;
      prescale_wr_o <= 1'b0;
      pretimeout_q <= 32'h0;
      pretimeout_wr_o <= 1'b0;
      window_open_q <= 32'h0;
      window_open_wr_o <= 1'b0;
      kick_q <= '0;
      kick_wr_o <= 1'b0;
      status_q <= '0;
      status_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_COUNT);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        timeout_wr_o <= wr_en && wa == A_TIMEOUT;
        if (wr_en && wa == A_TIMEOUT) timeout_q <= (timeout_q & ~wmask) | (wr_data & wmask);
      end
      begin
        prescale_wr_o <= wr_en && wa == A_PRESCALE;
        if (wr_en && wa == A_PRESCALE) prescale_q <= (prescale_q & ~wmask) | (wr_data & wmask);
      end
      begin
        pretimeout_wr_o <= wr_en && wa == A_PRETIMEOUT;
        if (wr_en && wa == A_PRETIMEOUT) pretimeout_q <= (pretimeout_q & ~wmask) | (wr_data & wmask);
      end
      begin
        window_open_wr_o <= wr_en && wa == A_WINDOW_OPEN;
        if (wr_en && wa == A_WINDOW_OPEN) window_open_q <= (window_open_q & ~wmask) | (wr_data & wmask);
      end
      begin
        kick_wr_o <= wr_en && wa == A_KICK;
        if (wr_en && wa == A_KICK) kick_q <= (kick_q & ~wmask) | (wr_data & wmask);
      end
      begin
        status_wr_o <= wr_en && wa == A_STATUS;
        if (wr_en && wa == A_STATUS) status_q <= (status_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[3-1:0];
  assign timeout_o = timeout_q[32-1:0];
  assign prescale_o = prescale_q[32-1:0];
  assign pretimeout_o = pretimeout_q[32-1:0];
  assign window_open_o = window_open_q[32-1:0];
  assign kick_o = kick_q[32-1:0];
  assign status_o = status_q[4-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = 32'(ctrl_i);
      A_TIMEOUT: rd_data = timeout_q;
      A_PRESCALE: rd_data = prescale_q;
      A_PRETIMEOUT: rd_data = pretimeout_q;
      A_WINDOW_OPEN: rd_data = window_open_q;
      A_STATUS: rd_data = 32'(status_i);
      A_COUNT: rd_data = 32'(count_i);
      default: begin
      end
    endcase
  end
endmodule
